"use client";

import { type RefObject, useEffect } from "react";
import { createLightField, type LightFieldOptions } from "./light";
import { createProximity, type ProximityOptions } from "./proximity";
import { createIndicator, type IndicatorOptions } from "./indicator";
import { createSwipe, type SwipeOptions } from "./swipe";
import { createReveal, type RevealOptions } from "./reveal";

/**
 * React bindings for the interaction engines. Options are read once per mount; pass a `key` (or change a primitive in
 * `deps`) to rebuild. The engines never set React state, so pointer movement causes no re-renders.
 */
export function useProximity(ref: RefObject<HTMLElement | null>, options?: ProximityOptions, deps: unknown[] = []) {
  // biome-ignore lint/correctness/useExhaustiveDependencies: options are read once by design
  useEffect(() => {
    if (!ref.current) return;
    return createProximity(ref.current, options);
  }, deps);
}

